from pathlib import Path
from html.parser import HTMLParser
from urllib.parse import urljoin, urlsplit
import hashlib, json, re

base = 'https://www.contractsfinder.service.gov.uk/Search/Results?Keywords=data%20cleansing'
source = Path('products/services/contracts-finder-small-data-qa/raw/targeted-data-cleansing.html')
raw = source.read_bytes()

class NoticeLinks(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.current = None
        self.links = {}

    def handle_starttag(self, tag, attrs):
        if tag != 'a':
            return
        self.current = None
        url = urljoin(base, dict(attrs).get('href') or '')
        parsed = urlsplit(url)
        if parsed.scheme == 'https' and parsed.hostname == 'www.contractsfinder.service.gov.uk' and re.fullmatch(r'/notice/[0-9a-f-]{36}', parsed.path, re.I):
            self.current = (parsed._replace(query='', fragment='').geturl(), [])

    def handle_data(self, data):
        if self.current:
            self.current[1].append(data)

    def handle_endtag(self, tag):
        if tag == 'a' and self.current:
            url, parts = self.current
            label = ' '.join(' '.join(parts).split())
            if label or url not in self.links:
                self.links[url] = label
            self.current = None

parser = NoticeLinks()
parser.feed(raw.decode('utf-8', errors='replace'))
result = {'source_url': base, 'source_sha256': hashlib.sha256(raw).hexdigest(), 'notice_link_count': len(parser.links), 'notice_links': [{'url': url, 'label': label} for url, label in parser.links.items()], 'scope': 'Navigation from one saved search page. Notice status, relevance, deadlines and buyer requirements require original notice verification.'}
out = source.parent.parent / 'targeted-notice-links.json'
out.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'artifact': str(out), 'notice_link_count': len(parser.links)}))
